#include "CUDADataFormats/TrajectoryStateSoA.h"

using Vector5d = Eigen::Matrix<double, 5, 1>;
using Matrix5d = Eigen::Matrix<double, 5, 5>;

/**
 * Calculates a positive definite covariance matrix from a given vector.
 *
 * @param e input vector
 * @return calculated covariance matrix
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.5.
*/ 
  Matrix5d loadCov(Vector5d const& e) {
  Matrix5d cov;
  for (int i = 0; i < 5; ++i)
    cov(i, i) = e(i) * e(i);
  for (int i = 0; i < 5; ++i) {
    for (int j = 0; j < i; ++j) {
      double v = 0.3 * std::sqrt(cov(i, i) * cov(j, j));  // this makes the matrix pos defined
      cov(i, j) = (i + j) % 2 ? -0.4 * v : 0.1 * v;
      cov(j, i) = cov(i, j);
    }
  }
  return cov;
}

using TS = TrajectoryStateSoA<128>;

/**
 * @brief Tests the Threaded Sparse SoA implementation
 *
 * This function tests the correctness of the Threaded Sparse SoA implementation
 * by comparing the results of copying data to and from the sparse representation
 * It checks that the copied values match the original values within a small tolerance
  
 * @class TS
 *
 * Represents a threaded sparse matrix or vector
  
 * @struct Vector5d
 *
 * A 5-dimensional vector class
  
 * @struct Matrix5d
 *
 * A 5x5 matrix class
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.5.
*/ 
 void testTSSoA(TS* pts, int n) {
  assert(n <= 128);

  Vector5d par0;
  par0 << 0.2, 0.1, 3.5, 0.8, 0.1;
  Vector5d e0;
  e0 << 0.01, 0.01, 0.035, -0.03, -0.01;
  auto cov0 = loadCov(e0);

  TS& ts = *pts;

  int first = 0;

  for (int i = first; i < n; i += 1) {
    ts.copyFromDense(par0, cov0, i);
    Vector5d par1;
    Matrix5d cov1;
    ts.copyToDense(par1, cov1, i);
    Vector5d delV = par1 - par0;
    Matrix5d delM = cov1 - cov0;
    for (int j = 0; j < 5; ++j) {
      assert(std::abs(delV(j)) < 1.e-5);
      for (auto k = j; k < 5; ++k) {
        assert(cov0(k, j) == cov0(j, k));
        assert(cov1(k, j) == cov1(j, k));
        assert(std::abs(delM(k, j)) < 1.e-5);
      }
    }
  }
}

/**
 * Brief description of the main function 
 * Detailed description of the main function 
 * @param none
 * @return integer value indicating program execution status
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.5.
*/ 
int main() {
  TS ts;

  testTSSoA(&ts, 128);
}
